{
  "technical_and_design_decisions": [
    "Target platform is the Spring XD 1.1 codebase (Java 8, Spring Framework 4.x, Gradle build system), consistent with the 1.0-to-1.1 migration context of the user stories.",
    "U1: Deliver migration support as a combination of a documented 1.0->1.1 module migration guide plus hands-on verification by porting representative sample custom modules (source/sink/processor) to the 1.1 module API; no automated migration tooling will be built.",
    "U2: The Pig sample will be implemented as an XD batch job module wrapping a Pig script via Spring Hadoop (SHDP), with a small integration test and README documentation.",
    "U3/U4: Windows support will reuse the existing Gradle build; Unix shell scripts will be mirrored with Windows batch/PowerShell equivalents, and path/line-ending/encoding issues in build and test code will be fixed rather than introducing a separate build system.",
    "U4: A dedicated EC2 Windows Server AMI will be provisioned (JDK, Git, Gradle, XD runtime preinstalled); acceptance tests will run via a new Jenkins CI plan triggered on demand and nightly.",
    "U5: Spark Streaming processors will be implemented twice as separate XD processor modules - one in Java 8 using lambdas and one in Scala - both built against Spark 1.x streaming API, sharing a common test fixture and documented usage examples.",
    "U7: Kafka support will be upgraded by first backporting XD-specific Kafka enhancements into the Spring Integration Kafka extension, then bumping XD to the SI Kafka GA release and adapting to any API changes.",
    "U8: Hadoop integration will be upgraded to the Spring Hadoop (SHDP) GA release via dependency version bump plus adaptation of any changed APIs/configuration.",
    "U6: The copyright year is maintained in the documentation build configuration (Asciidoc/DocBook attributes) so the reference guide PDF regenerates with the updated 2015 notice.",
    "All code changes follow the existing project conventions: Gradle modules, JUnit-based unit/integration tests, and documentation in the reference guide."
  ],
  "assumptions": [
    "A single developer (the author) performs all work; estimates are pure effort in work-hours, not calendar time, and exclude waiting/review time by third parties.",
    "The developer is already familiar with the Spring XD codebase, Gradle, Spark, Kafka, Spring Integration, Spring Hadoop, and AWS EC2, so no learning-curve allowance is included.",
    "An AWS account with permissions to create Windows Server AMIs and EC2 instances is available at no additional procurement effort; a Jenkins CI server is available for the new Windows acceptance-test plan.",
    "The XD 1.0 and 1.1 codebases, existing acceptance-test suite, and sample custom modules are available as starting points.",
    "The SI Kafka GA and SHDP GA releases are publicly available and largely API-compatible; upgrade effort covers adaptation and regression verification only.",
    "No clarifying information is required from stakeholders; ambiguities are resolved by the technical decisions listed above.",
    "One work-hour equals one hour of focused development, testing, or documentation work."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Project analysis and environment setup",
      "activity_description": "Review all eight user stories, inspect the XD 1.0/1.1 codebases, set up development environments (Linux and Windows), CI access, and AWS credentials.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A2",
      "activity_name": "U1 - Analyze XD 1.0 to 1.1 module API differences",
      "activity_description": "Diff module definition, packaging, and deployment APIs between XD 1.0 and 1.1; catalogue breaking changes affecting custom modules and data pipelines.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A3",
      "activity_name": "U1 - Port and validate sample custom modules",
      "activity_description": "Port representative custom source, processor, and sink modules from 1.0 to 1.1, run them against existing data pipelines to verify operationalization works.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A4",
      "activity_name": "U1 - Write migration guide",
      "activity_description": "Author the 1.0-to-1.1 migration documentation covering module porting steps, pipeline migration, and new 1.1 features relevant to users.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A5",
      "activity_name": "U2 - Implement Pig job sample module",
      "activity_description": "Create a sample Pig script and an XD batch job module that executes it via Spring Hadoop, including configuration metadata.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A6",
      "activity_name": "U2 - Test and document Pig sample",
      "activity_description": "Add an integration test running the Pig job in XD and write reference documentation/README showing how to integrate Pig jobs in XD.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A7",
      "activity_name": "U3 - Fix Windows build issues",
      "activity_description": "Resolve path separator, line-ending, encoding, and shell-script problems in the Gradle build; provide Windows batch/PowerShell script equivalents; fix platform-sensitive tests.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A8",
      "activity_name": "U3 - Validate full build on Windows",
      "activity_description": "Run the complete XD build with unit and integration tests on a Windows machine, iterate on failures until the build is green, and document Windows build instructions.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A9",
      "activity_name": "U4 - Provision EC2 Windows image",
      "activity_description": "Create and configure a Windows Server AMI on EC2 with JDK, Git, Gradle, and XD runtime prerequisites; script the provisioning for repeatability.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A10",
      "activity_name": "U4 - Adapt and run acceptance tests on Windows",
      "activity_description": "Adapt the acceptance-test suite for Windows (paths, process management, ports), execute the full suite on the EC2 Windows environment, and fix discovered issues.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A11",
      "activity_name": "U4 - Create Windows acceptance-test CI build",
      "activity_description": "Configure a Jenkins CI plan that launches/uses the EC2 Windows node and runs the acceptance-test suite on a scheduled and on-demand basis.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A12",
      "activity_name": "U5 - Design Spark Streaming processor modules",
      "activity_description": "Define the XD processor module contract for Spark Streaming (options, input/output binding, checkpointing) shared by the Java and Scala implementations.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A13",
      "activity_name": "U5 - Implement Java Spark Streaming processor",
      "activity_description": "Implement the Spark Streaming processor module in Java 8 using Java lambdas against the Spark 1.x streaming API.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A14",
      "activity_name": "U5 - Implement Scala Spark Streaming processor",
      "activity_description": "Implement the equivalent Spark Streaming processor module in Scala, including the Scala build wiring in Gradle.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A15",
      "activity_name": "U5 - Test and document Spark Streaming processors",
      "activity_description": "Write unit and integration tests for both processor variants and produce user documentation with example stream definitions demonstrating the capabilities.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A16",
      "activity_name": "U6 - Update copyright in reference guide PDF",
      "activity_description": "Update the copyright year from 2014 to 2015 in the documentation build configuration and regenerate/verify the reference guide PDF.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A17",
      "activity_name": "U7 - Backport Kafka XD changes to SI Kafka",
      "activity_description": "Backport XD-specific Kafka enhancements and fixes into the Spring Integration Kafka extension in preparation for the GA release alignment.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A18",
      "activity_name": "U7 - Upgrade XD to SI Kafka GA",
      "activity_description": "Bump the Kafka integration dependency to the SI Kafka GA release, adapt XD Kafka source/sink modules to API changes, and run Kafka-related integration tests.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A19",
      "activity_name": "U8 - Upgrade to SHDP GA release",
      "activity_description": "Upgrade the Spring Hadoop dependency to the GA release, adapt configuration and Hadoop job modules (including the Pig sample) to any changes, and verify with tests.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A20",
      "activity_name": "Cross-cutting integration and regression testing",
      "activity_description": "Run full regression and integration test suites across Linux and Windows covering all increment changes (migration, Pig, Spark, Kafka, SHDP) and fix defects found.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A21",
      "activity_name": "Final documentation and release preparation",
      "activity_description": "Consolidate reference guide updates, release notes for all eight user stories, version bumps, and final packaging verification of the increment.",
      "most_likely_effort": 16
    }
  ],
  "reported_total": {
    "most_likely_effort": 470
  }
}
